/**
 * The operations on notifications an actor calls: reading their own inbox and how many
 * notifications still wait for them, and, for a person, marking what they saw. An inbox belongs to
 * one membership, and no role opens another recipient's. Notifications are generated by `NotificationProjection`
 * and accepted by turns and deliveries, never here.
 *
 * @since 0.1.0
 */

import * as Context from "effect/Context"
import * as Crypto from "effect/Crypto"
import * as DateTime from "effect/DateTime"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
import * as Option from "effect/Option"
import * as Schema from "effect/Schema"
import * as Authorization from "../authorization/Authorization.ts"
import * as CoreError from "../error/CoreError.ts"
import * as Actor from "../identity/Actor.ts"
import * as Event from "../journal/Event.ts"
import * as Journal from "../journal/Journal.ts"
import * as Publication from "../journal/Publication.ts"
import * as Operation from "../operation/Operation.ts"
import type * as Thread from "../thread/Thread.ts"
import * as ThreadActivityFacts from "../thread/ThreadActivityFacts.ts"
import * as ThreadQuery from "../thread/ThreadQuery.ts"
import * as Notification from "./Notification.ts"
import * as NotificationFacts from "./NotificationFacts.ts"
import * as NotificationInbox from "./NotificationInbox.ts"
import * as NotificationStore from "./NotificationStore.ts"

/**
 * What every notification operation can fail with: authorization, the store, and an input that
 * does not decode.
 *
 * @category errors
 * @since 0.1.0
 */
export type Error = CoreError.Denied | CoreError.Invalid | CoreError.Unavailable

/**
 * What reading a notification's source can fail with.
 *
 * @category errors
 * @since 0.1.0
 */
export type SourceError = CoreError.Denied | CoreError.Invalid | CoreError.Unavailable

/**
 * What reading the inbox can fail with: reading notifications, and reading their sources.
 *
 * @category errors
 * @since 0.1.0
 */
export type InboxError = CoreError.Denied | CoreError.Invalid | CoreError.Unavailable

/**
 * What marking notifications seen can fail with: one missing or another's, one already handled, and
 * an acting member who is not a person.
 *
 * @category errors
 * @since 0.1.0
 */
export type MarkSeenError =
  | CoreError.NotFound
  | CoreError.Denied
  | CoreError.Conflict
  | CoreError.Invalid
  | CoreError.Unavailable
  | CoreError.Uncertain

/**
 * The notification operations, one of `Core.Operations`.
 *
 * The acting member's inbox, its pending count, and marking what they saw, within one workspace.
 * Active membership is required; owning a role does not grant access to another recipient's inbox.
 * Reads use current state without opening a transaction. Marking seen records a
 * `NotificationFacts.Seen` for each notification. Reading a notification neither marks it seen nor
 * grants access to its source.
 *
 * @category services
 * @since 0.1.0
 */
export class NotificationService extends Context.Service<
  NotificationService,
  {
    /**
     * The acting member's notifications newest first, each with the timeline item it points to
     * while they may still read it, or without one where they may not.
     */
    readonly inbox: (
      options: NotificationInbox.Options
    ) => Effect.Effect<ReadonlyArray<NotificationInbox.Item>, InboxError, Actor.Actor>
    /** Record that the acting person saw their notification; source access is independent. */
    readonly markSeen: (
      notificationId: Notification.NotificationId
    ) => Effect.Effect<Notification.Notification, MarkSeenError, Actor.Actor>
    /**
     * Record that the acting person saw every notification still pending for them up to and
     * including `through`, in inbox order, so what arrives after the newest they saw stays pending.
     * Returns how many it marked.
     */
    readonly markSeenThrough: (
      through: NotificationStore.Cursor
    ) => Effect.Effect<number, Exclude<MarkSeenError, CoreError.NotFound | CoreError.Conflict>, Actor.Actor>
    /** How many notifications are still pending for the acting member, in all and by group. */
    readonly countPending: Effect.Effect<NotificationInbox.Counts, Error, Actor.Actor>
  }
>()("@amends-dev/core/notification/NotificationService") {}

const decodeInboxOptions = Schema.decodeEffect(Schema.toType(NotificationInbox.Options))
const sameRecipient = Schema.toEquivalence(Notification.Recipient)
const decodeCursor = Schema.decodeEffect(Schema.toType(NotificationStore.Cursor))
/** IDs in binary lexical order, as stores order them: by code point. */
const compareIds = (left: string, right: string) => {
  const a = Array.from(left, (char) => char.codePointAt(0) ?? 0),
    b = Array.from(right, (char) => char.codePointAt(0) ?? 0)
  for (let index = 0; index < Math.min(a.length, b.length); index++)
    if (a[index] !== b[index]) return a[index]! - b[index]!
  return a.length - b.length
}
/** Whether a notification comes at or before a cursor in inbox order. */
const isAtOrBefore = (record: Notification.Notification, cursor: NotificationStore.Cursor) => {
  const byTime = DateTime.toEpochMillis(record.recordedAt) - DateTime.toEpochMillis(cursor.recordedAt)
  return byTime < 0 || (byTime === 0 && compareIds(record.id, cursor.id) <= 0)
}
/** How many pending notifications one page lists. */
const seenBatch = 100

/**
 * Builds the notification operations over the store, the journal, and thread reads; each operation
 * resolves the actor and their current membership itself.
 *
 * @category constructors
 * @since 0.1.0
 */
export const make: Effect.Effect<
  NotificationService["Service"],
  never,
  | NotificationStore.NotificationStore
  | Authorization.Authorization
  | Journal.Journal
  | ThreadQuery.ThreadQuery
  | Crypto.Crypto
> = Effect.gen(function* () {
  const notificationStore = yield* NotificationStore.NotificationStore
  const authorization = yield* Authorization.Authorization
  const journal = yield* Journal.Journal
  const threadQuery = yield* ThreadQuery.ThreadQuery
  const crypto = yield* Crypto.Crypto

  /** The acting member as a recipient, once their membership is checked. */
  const requireRecipient = Effect.fnUntraced(function* () {
    yield* authorization.require([])
    const actor = yield* Actor.Actor
    return Notification.ofMember(actor.memberId, actor.identity)
  })

  /** The acting member's own notification; another recipient's reads as missing. */
  const requireOwn = Effect.fnUntraced(function* (notificationId: Notification.NotificationId) {
    const target = yield* requireRecipient()
    const id = yield* Schema.decodeEffect(Notification.NotificationId)(notificationId)
    const found = yield* notificationStore.get(id)
    if (Option.isNone(found) || !sameRecipient(found.value.recipient, target))
      return yield* new CoreError.NotFound({ resource: "Notification", id })
    return found.value
  })

  /**
   * The timeline item a notification the actor owns points to, while they may still read it. None
   * when they have lost access to it, or its source is not thread activity; access is current,
   * whatever the notification's state.
   */
  const findSource = Effect.fnUntraced(function* (notification: Notification.Notification) {
    if (
      notification.source.logId !== journal.log.id ||
      !Notification.Recipient.isAnyOf(["Human", "Agent"])(notification.recipient)
    )
      return Option.none<Thread.TimelineItem>()
    const found = yield* journal.log
      .getEntry(notification.source.entryId)
      .pipe(Effect.catchTag("SchemaError", Effect.die))
    if (Option.isNone(found)) return Option.none<Thread.TimelineItem>()
    const entry = found.value
    if (
      entry.payload.name !== ThreadActivityFacts.Recorded.name ||
      entry.payload.version !== ThreadActivityFacts.Recorded.version
    )
      return Option.none<Thread.TimelineItem>()
    const event = yield* Effect.orDie(Event.decode(ThreadActivityFacts.Recorded, entry))
    return yield* threadQuery.readTimelineItem(event.payload.activity.id).pipe(
      Effect.asSome,
      Effect.catchTag("CoreError.NotFound", () => Effect.succeedNone),
      Effect.catchReason("CoreError.Denied", "NotGranted", () => Effect.succeedNone)
    )
  })
  const inbox = Effect.fn("NotificationService.inbox")(function* (options: NotificationInbox.Options) {
    const target = yield* requireRecipient()
    const { pendingOnly = false, ...request } = yield* decodeInboxOptions(options)
    const records = yield* pendingOnly
      ? notificationStore.listLatestPendingByRecipient(target, request)
      : notificationStore.listLatestByRecipient(target, request)
    // One at a time: inside a caller's commit, the store takes one step at a time.
    return yield* Effect.forEach(records, (notification) =>
      Effect.map(
        findSource(notification),
        Option.match({
          onNone: (): NotificationInbox.Item => ({ notification }),
          onSome: (item): NotificationInbox.Item => ({ notification, source: item })
        })
      )
    )
  }, Operation.report)
  const markSeen = Effect.fn("NotificationService.markSeen")(
    function* (notificationId: Notification.NotificationId) {
      const notification = yield* requireOwn(notificationId)
      if (!Notification.Recipient.isAnyOf(["Human"])(notification.recipient))
        return yield* new CoreError.Denied({ reason: new CoreError.HumanRequired() })
      if (Notification.State.isAnyOf(["Seen"])(notification.state)) return notification
      if (!Notification.State.isAnyOf(["Pending"])(notification.state))
        return yield* new CoreError.Conflict({
          reason: new CoreError.AlreadyHandled({ notificationId: notification.id })
        })
      yield* journal.publish(NotificationFacts.Seen, { notificationId: notification.id })
      return yield* requireOwn(notification.id)
    },
    Publication.withActor,
    Effect.provideService(Crypto.Crypto, crypto),
    journal.commit,
    Operation.report
  )
  const markSeenThrough = Effect.fn("NotificationService.markSeenThrough")(
    function* (input: NotificationStore.Cursor) {
      const target = yield* requireRecipient()
      if (!Notification.Recipient.isAnyOf(["Human"])(target))
        return yield* new CoreError.Denied({ reason: new CoreError.HumanRequired() })
      const through = yield* decodeCursor(input)
      let marked = 0
      // What is marked leaves the pending list, so each page starts where the last one ended.
      while (true) {
        const page = yield* notificationStore.listPendingByRecipient(target, { limit: seenBatch })
        const due = page.filter((record) => isAtOrBefore(record, through))
        for (const record of due) yield* journal.publish(NotificationFacts.Seen, { notificationId: record.id })
        marked += due.length
        if (page.length < seenBatch || due.length < page.length) return marked
      }
    },
    Publication.withActor,
    Effect.provideService(Crypto.Crypto, crypto),
    journal.commit,
    Operation.report
  )
  const countPending = Effect.gen(function* () {
    const target = yield* requireRecipient()
    return {
      pending: yield* notificationStore.countPendingByRecipient(target),
      groups: yield* notificationStore.countPendingByGroup(target)
    }
  }).pipe(Effect.withSpan("NotificationService.countPending"), Operation.report)
  return NotificationService.of({ inbox, markSeen, markSeenThrough, countPending })
})

/**
 * Provide notification operations over the caller's workspace services.
 *
 * @category layers
 * @since 0.1.0
 */
export const layer = Layer.effect(NotificationService, make)
